with flagged as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 30 minutes then 1 else 0 end as is_new_session from device_readings), islands as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from flagged) select date_trunc('hour', reading_ts) as hour_window, sum(pressure) as total_pressure, count_if(device_code = 'DV-01') as dv_01_events, max(reading_ts) as last_seen from islands group by date_trunc('hour', reading_ts);
